select t2.*,
en.translate as english,en.translate_state as englishTranslateState,en.public_state as englishPublicState,
ru.translate as russian,ru.translate_state as russianTranslateState,ru.public_state as russianPublicState,
fra.translate as french,fra.translate_state as frenchTranslateState,fra.public_state as frenchPublicState,
spa.translate as spanish,spa.translate_state as spanishTranslateState,spa.public_state as spanishPublicState
zh.translate as chinese,zh.translate_state as chineseTranslateState,zh.public_state as chinesePublicState
from
t_product_relation t1 right JOIN t_entry_info t2 on t1.entry_id = t2.id
left join t_translate zh on t2.zh_trans_id = zh.id

    and zh.translate_state = #{entryInfoEntity.chineseTranslateState,jdbcType=VARCHAR}

left join t_translate en on t2.en_trans_id = en.id

    and en.translate_state = #{entryInfoEntity.englishTranslateState,jdbcType=VARCHAR}

left join t_translate ru on t2.ru_trans_id = ru.id

    and ru.translate_state = #{entryInfoEntity.russianTranslateState,jdbcType=VARCHAR}

left join t_translate fra on t2.fra_trans_id = fra.id

    and fra.translate_state = #{entryInfoEntity.frenchTranslateState,jdbcType=VARCHAR}

left join t_translate spa on t2.spa_trans_id = spa.id

    and spa.translate_state = #{entryInfoEntity.spanishTranslateState,jdbcType=VARCHAR}



